225	func (driver *Driver) applyAddressToConfig(
226		claim *resourceapi.ResourceClaim,
227		request string,
228		prefix netip.Prefix,
229		devicesCfg map[string]types.DeviceConfig,
230	) error {
231		if !prefix.IsValid() {
232			if prefix == (netip.Prefix{}) {
233				// treat zero address as "no address specified" and skip without error
234				return nil
235			}
236			return fmt.Errorf("invalid prefix %s for request %s in claim %s", prefix, request, claim.Name)
237		}
238	
239		family := "ipv6"
240		if prefix.Addr().Is4() {
241			family = "ipv4"
242		}
243	
244		cfg, found := devicesCfg[request]
245		if !found {
246			return fmt.Errorf("unable to find request %s in claim %s, static prefixes will not be applied", request, claim.Name)
247		}
248		if family == "ipv4" {
249			cfg.IPv4Addr = prefix
250		} else {
251			cfg.IPv6Addr = prefix
252		}
253		devicesCfg[request] = cfg
254	
255		return nil
256	}
